mapper.update:
update TBL_TVM_ORDER_TOPUP
TICKET_LOGIC_NUM = #{ticketLogicNum,jdbcType=VARCHAR}, TICKET_PHYSICS_NUM = #{ticketPhysicsNum,jdbcType=VARCHAR}, BEFORE_AMOUNT = #{beforeAmount,jdbcType=VARCHAR}, TRANS_AMOUNT = #{transAmount,jdbcType=VARCHAR}, AFTER_AMOUNT = #{afterAmount,jdbcType=VARCHAR}, STATUS = #{status,jdbcType=VARCHAR}, MSG = #{msg,jdbcType=VARCHAR}, CHANNEL = #{channel,jdbcType=VARCHAR}, PAYCENTER_ORDERNO = #{payCenterOrderNo,jdbcType=VARCHAR}, PAYCENTER_channelOrderNo = #{payCenterChannelOrderNo,jdbcType=VARCHAR}, PAY_TYPE = #{payType,jdbcType=VARCHAR}, URL = #{url,jdbcType=VARCHAR}, UPDATE_TIME = #{updateTime,jdbcType=VARCHAR}, RSV1 = #{rsv1,jdbcType=VARCHAR}, RSV2 = #{rsv2,jdbcType=VARCHAR},
where ORDER_NO = #{orderNo,jdbcType=VARCHAR}

mapper.sql:
WHERE 1 = 1

    AND t.ORDER_NO = #{orderNo,jdbcType=VARCHAR}


    AND t.PAYCENTER_ORDERNO = #{payCenterOrderNo,jdbcType=VARCHAR}


    AND t.DEVICE_ID = #{deviceId,jdbcType=VARCHAR}


    AND t.TICKET_LOGIC_NUM = #{ticketLogicNum,jdbcType=VARCHAR}


    AND t.STATUS = #{status,jdbcType=VARCHAR}


    AND t.CHANNEL = #{channel,jdbcType=VARCHAR}


    AND t.CREATE_TIME >= #{beginTime,jdbcType=VARCHAR}


    AND t.CREATE_TIME <= #{endTime,jdbcType=VARCHAR}

mapper.select:
SELECT page.* FROM ( SELECT t.ORDER_NO, t.TICKET_LOGIC_NUM, t.TICKET_PHYSICS_NUM, t.BEFORE_AMOUNT, t.TRANS_AMOUNT, t.AFTER_AMOUNT, t.STATUS, t.MSG, t.CHANNEL, t.PAY_TYPE, t.PAYCENTER_ORDERNO, t.PAYCENTER_CHANNELORDERNO, t.DEVICE_ID, t.RSV2, t.CREATE_TIME, t.UPDATE_TIME, n.TOPUP_STATUS AS NOTIY_STATUS, ROW_NUMBER() OVER (ORDER BY t.CREATE_TIME DESC, t.ORDER_NO DESC) AS rn FROM TBL_TVM_ORDER_TOPUP t LEFT JOIN ( SELECT ORDER_NO, TOPUP_STATUS, ROW_NUMBER() OVER (PARTITION BY ORDER_NO ORDER BY CREATE_TIME DESC) AS rn FROM TBL_TVM_Topup_Notiy ) n ON n.ORDER_NO = t.ORDER_NO AND n.rn = 1
) page WHERE page.rn > #{offset} AND page.rn <= #{offsetEnd}
AND page.NOTIY_STATUS = #{topupStatus,jdbcType=VARCHAR}

SELECT COUNT(1) FROM ( SELECT t.ORDER_NO, n.TOPUP_STATUS AS NOTIY_STATUS FROM TBL_TVM_ORDER_TOPUP t LEFT JOIN ( SELECT ORDER_NO, TOPUP_STATUS, ROW_NUMBER() OVER (PARTITION BY ORDER_NO ORDER BY CREATE_TIME DESC) AS rn FROM TBL_TVM_Topup_Notiy ) n ON n.ORDER_NO = t.ORDER_NO AND n.rn = 1
) c
WHERE c.NOTIY_STATUS = #{topupStatus,jdbcType=VARCHAR}
